formulas.expression:
IF(
  {!IncludeEcologySurvey.value},
  IF(
    AND(
      {!IncludeNaturalEnglandNRWAssent.value},
      {!IncludeLPA_Consultation.value},
      {!IncludeHistoricEnglandCadwConsent.value}
    ),
    "6. ",
    IF(
      OR(
        AND({!IncludeNaturalEnglandNRWAssent.value}, {!IncludeLPA_Consultation.value}),
        AND({!IncludeNaturalEnglandNRWAssent.value}, {!IncludeHistoricEnglandCadwConsent.value}),
        AND({!IncludeLPA_Consultation.value}, {!IncludeHistoricEnglandCadwConsent.value})
      ),
      "5. ",
      IF(
        OR(
          {!IncludeNaturalEnglandNRWAssent.value},
          {!IncludeLPA_Consultation.value},
          {!IncludeHistoricEnglandCadwConsent.value}
        ),
        "4. ",
        "3. "
      )
    )
  ),
  NULL
)
